// Canadian Grade 1 stakes races (run at Woodbine).
// Source: Wikipedia – Category:Grade 1 stakes races in Canada.
// Distances normalized to meters. dayOfYear schedules each race on the
// game's 365-day annual cycle (day 1 = Jan 1).

import { TRACK_BY_NAME } from "./tracks";

export type Grade = "G1" | "G2" | "G3";

// UUID v4 generator for race UUIDs
const generateUUID = () => {
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === "x" ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
};

export type GradedRace = {
  uuid: string; // Unique identifier for this race
  key: string;
  name: string;
  track: string; // Track name (for display)
  trackId: string; // Track UUID reference
  country?: string;
  grade: Grade;
  distance: number;
  surface: "Turf" | "Dirt" | "Synthetic";
  purse: number;
  dayOfYear: number;
  restrictions?: {
    minAge?: number;
    maxAge?: number;
    gender?:
      | "colt"
      | "filly"
      | "horse"
      | "mare"
      | "fillies"
      | "mares"
      | "colts"
      | "fillies-and-mares"
      | "colts-and-fillies";
    // Hemisphere-specific age restrictions (e.g., for Dubai races)
    minAgeNorthern?: number;
    minAgeSouthern?: number;
  };
  note?: string; // e.g. "Fillies & Mares" — display-only
};

function doy(month: number, day: number): number {
  const cum = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];
  return cum[month - 1] + day;
}

function getCountry(track: string): string {
  const trackToCountry: Record<string, string> = {
    // Canada
    Woodbine: "Canada",
    "Fort Erie": "Canada",
    "Century Mile": "Canada",
    Hastings: "Canada",
    // UAE
    Meydan: "UAE",
    "Abu Dhabi": "UAE",
    "Jebel Ali": "UAE",
    // Argentina
    "Hipódromo de San Isidro": "Argentina",
    "Hipódromo Argentino de Palermo": "Argentina",
    "Hipódromo de La Plata": "Argentina",
    // Brazil
    "Hipódromo da Gávea": "Brazil",
    "Hipódromo Cidade Jardim": "Brazil",
    // Chile
    "Valparaiso Sporting Club": "Chile",
    "Club Hípico de Santiago": "Chile",
    "Hipódromo Chile": "Chile",
    // Scandinavia
    "Bro Park": "Sweden",
    Øvrevoll: "Norway",
    Klampenborg: "Denmark",
    Jägersro: "Sweden",
    // Japan
    Tokyo: "Japan",
    Chukyo: "Japan",
    Hanshin: "Japan",
    Nakayama: "Japan",
    Kyoto: "Japan",
    Kanazawa: "Japan",
    Monbetsu: "Japan",
    Nagoya: "Japan",
    Sonoda: "Japan",
    // Italy
    Capannelle: "Italy",
    "San Siro": "Italy",
    // Hong Kong
    "Sha Tin": "Hong Kong",
    "Happy Valley": "Hong Kong",
    // Great Britain
    Newmarket: "Great Britain",
    "Newmarket (July)": "Great Britain",
    Newbury: "Great Britain",
    Epsom: "Great Britain",
    Ascot: "Great Britain",
    Sandown: "Great Britain",
    York: "Great Britain",
    Haydock: "Great Britain",
    Chester: "Great Britain",
    Doncaster: "Great Britain",
    Goodwood: "Great Britain",
    // France
    "Saint-Cloud": "France",
    Longchamp: "France",
    Deauville: "France",
    Chantilly: "France",
    Vichy: "France",
    Toulouse: "France",
    // Ireland
    Curragh: "Ireland",
    Leopardstown: "Ireland",
    Navan: "Ireland",
    Naas: "Ireland",
    // Germany
    Düsseldorf: "Germany",
    Cologne: "Germany",
    "Baden-Baden": "Germany",
    Hanover: "Germany",
    Krefeld: "Germany",
    // Turkey
    Veliefendi: "Turkey",
    // Austria
    Vienna: "Austria",
    Klagenfurt: "Austria",
    // Belgium
    Ostend: "Belgium",
    Mons: "Belgium",
    // Czech Republic
    Prague: "Czech Republic",
    Most: "Czech Republic",
    "Karlovy Vary": "Czech Republic",
    // Hungary
    "Kincsem Park": "Hungary",
    // Spain
    Madrid: "Spain",
    "San Sebastián": "Spain",
    "Dos Hermanas": "Spain",
  };
  return trackToCountry[track] || "Other";
}

export function getRaceCountry(race: GradedRace): string {
  return race.country || getCountry(race.track);
}

export { getCountry };

